"items\" children={items} />}\r\n                renderItem={(item, isHighlighted) =>\r\n                    <div className={`item ${isHighlighted ? 'highlighted' : ''}`} key={item.id}>\r\n                        {item.value}\r\n                    </div>\r\n                }\r\n                inputProps={{\r\n                    className: 'form-control',\r\n                    placeholder: 'nickname or full name'\r\n                }}\r\n                value={this.props.value}\r\n                onChange={this.props.onChange}\r\n                onSelect={this.props.onSelect}\r\n            />\r\n        );\r\n    }\r\n}","import React, { PureComponent } from 'react';\r\n\r\nimport EmployeeAutocomplete from '../../supervisor/table/EmployeeAutocomplete';\r\n\r\nexport default class THead extends PureComponent {\r\n    constructor(props) {\r\n        super(props);\r\n\r\n        this.state = {\r\n            value: '',\r\n            employee: null\r\n        };\r\n    }\r\n\r\n    handleChange = event => {\r\n        const value = event.target.value;\r\n\r\n        this.setState({ value });\r\n        this.props.onSearchEmployees(value);\r\n    };\r\n\r\n    handleSelect = (value, item) => {\r\n        this.setState({ value, employee: item });\r\n    };\r\n\r\n    handleAddEmployee = () => {\r\n        const employee = this.state.employee;\r\n        if (employee !== null) {\r\n            this.props.onAddEmployee(employee);\r\n            this.setState({ value: '', employee: null });\r\n        }\r\n    };\r\n\r\n    render() {\r\n        const { employeeOptions } = this.props;\r\n\r\n        return (\r\n            <thead>\r\n                <tr>\r\n                    <th colSpan={2}>\r\n                        <div className=\"header-control\">\r\n                            <div>Employee</div>\r\n                            <EmployeeAutocomplete value={this.state.value}\r\n                                options={employeeOptions}\r\n                                onChange={this.handleChange}\r\n                                onSelect={this.handleSelect}\r\n                            />\r\n                            <a href=\"javascript:;\" onClick={this.handleAddEmployee}>+ Add to list</a>\r\n                        </div>\r\n                    </th>\r\n                </tr>\r\n                <tr>\r\n                    <th>Employee</th>\r\n                    <th />\r\n                </tr>\r\n            </thead>\r\n        );\r\n    }\r\n}","import React, { PureComponent } from 'react';\r\n\r\nimport DropdownOrder from '../../../../shared/components/DropdownOrder';\r\nimport { moveUp, moveDown, moveTop, moveBottom } from '../../supervisor/common.functions';\r\n\r\nexport default class Row extends PureComponent {\r\n    handleRemoveEmployee = () => {\r\n        const { ownerId } = this.props.data;\r\n        this.props.onRemoveEmployee(ownerId);\r\n    };\r\n\r\n    render() {\r\n        const { data } = this.props;\r\n        return (\r\n            <tr>\r\n                <td className=\"align-left cell-name\">\r\n                    <div className=\"wrapper\">\r\n                        <div>{data.nickname}</div>\r\n                        <DropdownOrder id={`dropdown${data.ownerId}`}\r\n                            onMoveUp={() => moveUp(this)}\r\n                            onMoveDown={() => moveDown(this)}\r\n                            onMoveTop={() => moveTop(this)}\r\n                            onMoveBottom={() => moveBottom(this)}\r\n                        />\r\n                    </div>\r\n                </td>\r\n                <td>\r\n                    <a className=\"fa fa-times fa-lg icon-delete\" href=\"javascript:;\"\r\n                        onClick={this.handleRemoveEmployee}\r\n                    />\r\n                </td>\r\n            </tr>\r\n        );\r\n    }\r\n}","import React, { PureComponent } from 'react';\r\n\r\nimport THead from './THead';\r\nimport Row from './Row';\r\n\r\nexport default class Table extends PureComponent {\r\n    render() {\r\n        const { data, employeeOptions } = this.props;\r\n\r\n        return (\r\n            <table className=\"table table-custom\">\r\n                <THead employeeOptions={employeeOptions}\r\n                    onSearchEmployees={this.props.onSearchEmployees}\r\n                    onAddEmployee={this.props.onAddEmployee}\r\n                />\r\n                <tbody>\r\n                    {\r\n                        data.length === 0 &&\r\n                        <tr className=\"nodata\"><td colSpan={2}>No information available</td></tr>\r\n                    }\r\n                    {\r\n                        data.length > 0 &&\r\n                        data.map((manager, index) =>\r\n                            <Row key={`row${index}`} data={manager}\r\n                                onRemoveEmployee={this.props.onRemoveEmployee}\r\n                                onChangeOrder={this.props.onChangeOrder}\r\n                            />\r\n                        )\r\n                    }\r\n                </tbody>\r\n            </table>\r\n        );\r\n    }\r\n}","import React, { Component, Fragment } from 'react';\r\nimport { Button } from 'react-bootstrap';\r\nimport { toast } from 'react-toastify';\r\nimport axios from 'axios';\r\n\r\nimport { axiosError, blockUI, unblockUI, resolveClientUrl } from '../../../shared/common.functions';\r\nimport { getSupervisors, editTeamSupervisor, editEmployeeSupervisor, reorderSupervisor } from '../supervisor/common.functions';\r\nimport ToastLayout from '../../../shared/layouts/ToastLayout';\r\nimport Table from './table/table';\r\n\r\nconst PageType = {\r\n    Team: 1,\r\n    Employee: 2\r\n};\r\n\r\nexport default class DisciplineManager extends Component {\r\n    constructor(props) {\r\n        super(props);\r\n\r\n        this.state = {\r\n            managers: [],\r\n            employeeOptions: []\r\n        };\r\n\r\n        this.roleId = document.getElementById('RoleId').value;\r\n    }\r\n\r\n    componentDidMount() {\r\n        this.getDisciplineManagers();\r\n    }\r\n\r\n    getEmployees = query => {\r\n        if (query.trim().length > 1) {\r\n            const excludeIds = this.state.managers.map(item => item.ownerId).join(',');\r\n            getSupervisors(query, this.roleId, excludeIds).then(response => {\r\n                const employeeOptions = response.data.map(item => {\r\n                    return {\r\n                        id: item.id,\r\n                        nickname: item.nickName,\r\n                        fullName: item.fullName,\r\n                        value: `${item.nickName} (${item.companyName})`,\r\n                        companyName: item.companyName !== null ? item.companyName : \"\",\r\n                    };\r\n                });\r\n\r\n                this.setState({ employeeOptions: employeeOptions });\r\n            }).catch(axiosError);\r\n        } else {\r\n            this.setState({ employeeOptions: [] });\r\n        }\r\n    };\r\n\r\n    getDisciplineManagers = () => {\r\n        blockUI();\r\n        if (this.props.pageType === PageType.Team) {\r\n            axios({\r\n                url: resolveClientUrl('Team/GetDisciplineManagerByTeamId'),\r\n                method: 'GET',\r\n                headers: { 'X-Requested-With': 'XMLHttpRequest' },\r\n                params: {\r\n                    teamId: this.props.objectId\r\n                }\r\n            }).then(response => {\r\n                this.setState({ managers: response.data });\r\n            }).catch(axiosError).then(() => unblockUI());\r\n        } else {\r\n            axios({\r\n                url: resolveClientUrl('Employee/GetDisciplineManagerByEmployeeId'),\r\n                method: 'GET',\r\n                headers: { 'X-Requested-With': 'XMLHttpRequest' },\r\n                params: {\r\n                    employeeId: this.props.objectId\r\n                }\r\n            }).then(response => {\r\n                this.setState({ managers: response.data });\r\n            }).catch(axiosError).then(() => unblockUI());\r\n        }\r\n    };\r\n\r\n    handleAddEmployee = employee => {\r\n        const managers = [...this.state.managers, \r\n            { \r\n                ownerId: employee.id, \r\n                nickname: employee.value, \r\n                fullName: employee.fullName,\r\n                companyName: employee.companyName\r\n            }];\r\n        this.setState({ managers, employeeOptions: [] });\r\n    };\r\n\r\n    handleRemoveEmployee = employeeId => {\r\n        const managers = [...this.state.managers],\r\n            index = managers.findIndex(item => item.ownerId === employeeId);\r\n        managers.splice(index, 1);\r\n        this.setState({ managers });\r\n    };\r\n\r\n    handleChangeOrder = (key, employeeId) => {\r\n        const vm = this;\r\n        reorderSupervisor(key, employeeId, [...this.state.managers], function (managers) {\r\n            vm.setState({ managers });\r\n        });\r\n    };\r\n\r\n    handleSave = () => {\r\n        const totalItems = this.state.managers.length;\r\n        const supervisors = [];\r\n        for (let i = 0; i < totalItems; i++) {\r\n            supervisors.push({\r\n                ownerId: this.state.managers[i].ownerId,\r\n                displayOrder: i + 1\r\n            });\r\n        }\r\n        if (this.props.pageType === PageType.Team) {\r\n            editTeamSupervisor(this.props.objectId, this.roleId, supervisors, toast);\r\n        } else {\r\n            editEmployeeSupervisor(this.props.objectId, this.roleId, supervisors, toast);\r\n        }\r\n    };\r\n\r\n    render() {\r\n        const { employeeOptions, managers } = this.state;\r\n\r\n        return (\r\n            <Fragment>\r\n                <ToastLayout />\r\n                <Table data={managers}\r\n                    employeeOptions={employeeOptions}\r\n                    onSearchEmployees={this.getEmployees}\r\n                    onAddEmployee={this.handleAddEmployee}\r\n                    onRemoveEmployee={this.handleRemoveEmployee}\r\n                    onChangeOrder={this.handleChangeOrder}\r\n                />\r\n                <Button onClick={this.handleSave} bsStyle=\"primary\">Save</Button>\r\n                <a className=\"btn btn-default\"\r\n                    href={resolveClientUrl(`${this.props.pageType === PageType.Team ? \r\n                        \"GroupTeam/TeamSupervisor\"\r\n                        : \"GroupEmployeeList/Edit\"}/${this.props.objectId}`)\r\n                    }\r\n                >Back</a>\r\n            </Fragment>\r\n        );\r\n    }\r\n}","import React from 'react';\r\nimport ReactDOM from 'react-dom';\r\nimport DisciplineManager from './DisciplineManager';\r\n\r\nReactDOM.render(\r\n    <DisciplineManager pageType={1} objectId={document.getElementById('TeamId').value} />,\r\n    document.getElementById('discipline-wrapper')\r\n);\r\n"],"sourceRoot":""}
