tDisciplineManagers();\r\n    }\r\n\r\n    getEmployees = query => {\r\n        if (query.trim().length > 1) {\r\n            const excludeIds = this.state.managers.map(item => item.ownerId).join(',');\r\n            getSupervisors(query, this.roleId, excludeIds).then(response => {\r\n                const employeeOptions = response.data.map(item => {\r\n                    return {\r\n                        id: item.id,\r\n                        nickname: item.nickName,\r\n                        fullName: item.fullName,\r\n                        value: `${item.nickName} (${item.companyName})`,\r\n                        companyName: item.companyName !== null ? item.companyName : \"\",\r\n                    };\r\n                });\r\n\r\n                this.setState({ employeeOptions: employeeOptions });\r\n            }).catch(axiosError);\r\n        } else {\r\n            this.setState({ employeeOptions: [] });\r\n        }\r\n    };\r\n\r\n    getDisciplineManagers = () => {\r\n        blockUI();\r\n        if (this.props.pageType === PageType.Team) {\r\n            axios({\r\n                url: resolveClientUrl('Team/GetDisciplineManagerByTeamId'),\r\n                method: 'GET',\r\n                headers: { 'X-Requested-With': 'XMLHttpRequest' },\r\n                params: {\r\n                    teamId: this.props.objectId\r\n                }\r\n            }).then(response => {\r\n                this.setState({ managers: response.data });\r\n            }).catch(axiosError).then(() => unblockUI());\r\n        } else {\r\n            axios({\r\n                url: resolveClientUrl('Employee/GetDisciplineManagerByEmployeeId'),\r\n                method: 'GET',\r\n                headers: { 'X-Requested-With': 'XMLHttpRequest' },\r\n                params: {\r\n                    employeeId: this.props.objectId\r\n                }\r\n            }).then(response => {\r\n                this.setState({ managers: response.data });\r\n            }).catch(axiosError).then(() => unblockUI());\r\n        }\r\n    };\r\n\r\n    handleAddEmployee = employee => {\r\n        const managers = [...this.state.managers, \r\n            { \r\n                ownerId: employee.id, \r\n                nickname: employee.value, \r\n                fullName: employee.fullName,\r\n                companyName: employee.companyName\r\n            }];\r\n        this.setState({ managers, employeeOptions: [] });\r\n    };\r\n\r\n    handleRemoveEmployee = employeeId => {\r\n        const managers = [...this.state.managers],\r\n            index = managers.findIndex(item => item.ownerId === employeeId);\r\n        managers.splice(index, 1);\r\n        this.setState({ managers });\r\n    };\r\n\r\n    handleChangeOrder = (key, employeeId) => {\r\n        const vm = this;\r\n        reorderSupervisor(key, employeeId, [...this.state.managers], function (managers) {\r\n            vm.setState({ managers });\r\n        });\r\n    };\r\n\r\n    handleSave = () => {\r\n        const totalItems = this.state.managers.length;\r\n        const supervisors = [];\r\n        for (let i = 0; i < totalItems; i++) {\r\n            supervisors.push({\r\n                ownerId: this.state.managers[i].ownerId,\r\n                displayOrder: i + 1\r\n            });\r\n        }\r\n        if (this.props.pageType === PageType.Team) {\r\n            editTeamSupervisor(this.props.objectId, this.roleId, supervisors, toast);\r\n        } else {\r\n            editEmployeeSupervisor(this.props.objectId, this.roleId, supervisors, toast);\r\n        }\r\n    };\r\n\r\n    render() {\r\n        const { employeeOptions, managers } = this.state;\r\n\r\n        return (\r\n            <Fragment>\r\n                <ToastLayout />\r\n                <Table data={managers}\r\n                    employeeOptions={employeeOptions}\r\n                    onSearchEmployees={this.getEmployees}\r\n                    onAddEmployee={this.handleAddEmployee}\r\n                    onRemoveEmployee={this.handleRemoveEmployee}\r\n                    onChangeOrder={this.handleChangeOrder}\r\n                />\r\n                <Button onClick={this.handleSave} bsStyle=\"primary\">Save</Button>\r\n                <a className=\"btn btn-default\"\r\n                    href={resolveClientUrl(`${this.props.pageType === PageType.Team ? \r\n                        \"GroupTeam/TeamSupervisor\"\r\n                        : \"GroupEmployeeList/Edit\"}/${this.props.objectId}`)\r\n                    }\r\n                >Back</a>\r\n            </Fragment>\r\n        );\r\n    }\r\n}","import React from 'react';\r\nimport ReactDOM from 'react-dom';\r\nimport DisciplineManager from './DisciplineManager';\r\n\r\nReactDOM.render(\r\n    <DisciplineManager pageType={1} objectId={document.getElementById('TeamId').value} />,\r\n    document.getElementById('discipline-wrapper')\r\n);\r\n","import React, { PureComponent } from 'react';\r\n\r\nimport DropdownOrder from '../../../../shared/components/DropdownOrder';\r\nimport { moveUp, moveDown, moveTop, moveBottom } from '../../supervisor/common.functions';\r\n\r\nexport default class Row extends PureComponent {\r\n    handleRemoveEmployee = () => {\r\n        const { ownerId } = this.props.data;\r\n        this.props.onRemoveEmployee(ownerId);\r\n    };\r\n\r\n    render() {\r\n        const { data } = this.props;\r\n        return (\r\n            <tr>\r\n                <td className=\"align-left cell-name\">\r\n                    <div className=\"wrapper\">\r\n                        <div>{data.nickname}</div>\r\n                        <DropdownOrder id={`dropdown${data.ownerId}`}\r\n                            onMoveUp={() => moveUp(this)}\r\n                            onMoveDown={() => moveDown(this)}\r\n                            onMoveTop={() => moveTop(this)}\r\n                            onMoveBottom={() => moveBottom(this)}\r\n                        />\r\n                    </div>\r\n                </td>\r\n                <td>\r\n                    <a className=\"fa fa-times fa-lg icon-delete\" href=\"javascript:;\"\r\n                        onClick={this.handleRemoveEmployee}\r\n                    />\r\n                </td>\r\n            </tr>\r\n        );\r\n    }\r\n}","import React, { PureComponent } from 'react';\r\n\r\nimport EmployeeAutocomplete from '../../supervisor/table/EmployeeAutocomplete';\r\n\r\nexport default class THead extends PureComponent {\r\n    constructor(props) {\r\n        super(props);\r\n\r\n        this.state = {\r\n            value: '',\r\n            employee: null\r\n        };\r\n    }\r\n\r\n    handleChange = event => {\r\n        const value = event.target.value;\r\n\r\n        this.setState({ value });\r\n        this.props.onSearchEmployees(value);\r\n    };\r\n\r\n    handleSelect = (value, item) => {\r\n        this.setState({ value, employee: item });\r\n    };\r\n\r\n    handleAddEmployee = () => {\r\n        const employee = this.state.employee;\r\n        if (employee !== null) {\r\n            this.props.onAddEmployee(employee);\r\n            this.setState({ value: '', employee: null });\r\n        }\r\n    };\r\n\r\n    render() {\r\n        const { employeeOptions } = this.props;\r\n\r\n        return (\r\n            <thead>\r\n                <tr>\r\n                    <th colSpan={2}>\r\n                        <div className=\"header-control\">\r\n                            <div>Employee</div>\r\n                            <EmployeeAutocomplete value={this.state.value}\r\n                                options={employeeOptions}\r\n                                onChange={this.handleChange}\r\n                                onSelect={this.handleSelect}\r\n                            />\r\n                            <a href=\"javascript:;\" onClick={this.handleAddEmployee}>+ Add to list</a>\r\n                        </div>\r\n                    </th>\r\n                </tr>\r\n                <tr>\r\n                    <th>Employee</th>\r\n                    <th />\r\n                </tr>\r\n            </thead>\r\n        );\r\n    }\r\n}","import React, { PureComponent } from 'react';\r\n\r\nimport THead from './THead';\r\nimport Row from './Row';\r\n\r\nexport default class Table extends PureComponent {\r\n    render() {\r\n        const { data, employeeOptions } = this.props;\r\n\r\n        return (\r\n            <table className=\"table table-custom\">\r\n                <THead employeeOptions={employeeOptions}\r\n                    onSearchEmployees={this.props.onSearchEmployees}\r\n                    onAddEmployee={this.props.onAddEmployee}\r\n                />\r\n                <tbody>\r\n                    {\r\n                        data.length === 0 &&\r\n                        <tr className=\"nodata\"><td colSpan={2}>No information available</td></tr>\r\n                    }\r\n                    {\r\n                        data.length > 0 &&\r\n                        data.map((manager, index) =>\r\n                            <Row key={`row${index}`} data={manager}\r\n                                onRemoveEmployee={this.props.onRemoveEmployee}\r\n                                onChangeOrder={this.props.onChangeOrder}\r\n                            />\r\n                        )\r\n                    }\r\n                </tbody>\r\n            </table>\r\n        );\r\n    }\r\n}","import axios from 'axios';\r\nimport { stringify } from 'qs';\r\n\r\nimport {\r\n    reorder,\r\n    resolveClientUrl,\r\n    axiosError,\r\n} from '../../../shared/common.functions';\r\n\r\nfunction getSupervisors(query, roleIds, excludeIds) {\r\n    return axios(resolveClientUrl('groupEmployeeList/GetSupervisors'), {\r\n        params: {\r\n            roleIds,\r\n            query,\r\n            excludeIds,\r\n        },\r\n    });\r\n}\r\n\r\nfunction getOrgChart(companyId = null) {\r\n    return axios({\r\n        method: 'GET',\r\n        url: resolveClientUrl('Team/GetOrgChart'),\r\n        headers: { 'X-Requested-With': 'XMLHttpRequest' },\r\n        params: companyId ? { companyId } : {},\r\n    });\r\n}\r\n\r\nfunction editEmployeeSupervisor(employeeId, roleId, supervisors, toastObj) {\r\n    axios({\r\n        url: resolveClientUrl('employee/EditEmployeeSupervisor'),\r\n        method: 'POST',\r\n        data: stringify({\r\n            employeeId,\r\n            roleId,\r\n            supervisors,\r\n        }),\r\n        headers: {\r\n            'X-Requested-With': 'XMLHttpRequest',\r\n            'Content-Type': 'application/x-www-form-urlencoded',\r\n        },\r\n    })\r\n        .then((response) => {\r\n            const data = response.data;\r\n            if (data.isSuccessful) {\r\n                toastObj.success('Updated Successfully!');\r\n            } else {\r\n                toastObj.error(data.message);\r\n            }\r\n        })\r\n        .catch(axiosError);\r\n}\r\n\r\nfunction editTeamSupervisor(teamId, roleId, supervisors, toastObj) {\r\n    axios({\r\n        url: resolveClientUrl('GroupTeam/EditTeamSupervisor'),\r\n        method: 'POST',\r\n        data: stringify({\r\n            teamId,\r\n            roleId,\r\n            supervisors,\r\n        }),\r\n        headers: {\r\n            'X-Requested-With': 'XMLHttpRequest',\r\n            'Content-Type': 'application/x-www-form-urlencoded',\r\n        },\r\n    })\r\n        .then((response) => {\r\n            const data = response.data;\r\n            if (data.isSuccessful) {\r\n                toastObj.success('Updated Successfully!');\r\n            } else {\r\n                toastObj.error(data.message);\r\n            }\r\n        })\r\n        .catch(axiosError);\r\n}\r\n\r\nfunction reorderSupervisor(key, employeeId, supervisors, callback) {\r\n    const totalItems = supervisors.length,\r\n        sourceIndex = supervisors.findIndex(\r\n            (item) => item.ownerId === employeeId\r\n        );\r\n    let destinationIndex = 0;\r\n\r\n    switch (key) {\r\n        case 'up':\r\n            destinationIndex = sourceIndex - 1;\r\n            break;\r\n        case 'down':\r\n            destinationIndex = sourceIndex + 1;\r\n            break;\r\n        case 'bottom':\r\n            destinationIndex = totalItems;\r\n            break;\r\n    }\r\n\r\n    if (\r\n        destinationIndex < 0 ||\r\n        destinationIndex > totalItems ||\r\n        sourceIndex === destinationIndex\r\n    ) {\r\n        return;\r\n    }\r\n\r\n    if (callback !== null && typeof callback === 'function') {\r\n        supervisors = reorder(supervisors, sourceIndex, destinationIndex);\r\n        callback(supervisors);\r\n    }\r\n}\r\n\r\nfunction moveUp(vm) {\r\n    const { ownerId } = vm.props.data;\r\n    vm.props.onChangeOrder('up', ownerId);\r\n}\r\n\r\nfunction moveDown(vm) {\r\n    const { ownerId } = vm.props.data;\r\n    vm.props.onChangeOrder('down', ownerId);\r\n}\r\n\r\nfunction moveTop(vm) {\r\n    const { ownerId } = vm.props.data;\r\n    vm.props.onChangeOrder('top', ownerId);\r\n}\r\n\r\nfunction moveBottom(vm) {\r\n    const { ownerId } = vm.props.data;\r\n    vm.props.onChangeOrder('bottom', ownerId);\r\n}\r\n\r\nexport {\r\n    getSupervisors,\r\n    getOrgChart,\r\n    editEmployeeSupervisor,\r\n    editTeamSupervisor,\r\n    reorderSupervisor,\r\n    moveUp,\r\n    moveDown,\r\n    moveTop,\r\n    moveBottom,\r\n};\r\n","import React, { PureComponent } from 'react';\r\nimport Autocomplete from 'react-autocomplete';\r\n\r\nexport default class EmployeeAutocomplete extends PureComponent {\r\n    render() {\r\n        return (\r\n            <Autocomplete\r\n                items={this.props.options}\r\n                getItemValue={item => item.value}\r\n                wrapperProps={{ className: 'react-autocomplete-wrapper' }}\r\n                wrapperStyle={{ display: 'block' }}\r\n                renderInput={props => <input type=\"text\" {...props} />}\r\n                renderMenu={items => <div className=\"items\" children={items} />}\r\n                renderItem={(item, isHighlighted) =>\r\n                    <div className={`item ${isHighlighted ? 'highlighted' : ''}`} key={item.id}>\r\n                        {item.value}\r\n                    </div>\r\n                }\r\n                inputProps={{\r\n                    className: 'form-control',\r\n                    placeholder: 'nickname or full name'\r\n                }}\r\n                value={this.props.value}\r\n                onChange={this.props.onChange}\r\n                onSelect={this.props.onSelect}\r\n            />\r\n        );\r\n    }\r\n}","import moment from 'moment';\r\nimport 'jquery-ui-bundle/jquery-ui';\r\n\r\nconst _rootUrl = document.getElementById('RootURL').value ? document.getElementById('RootURL').value : '/';\r\n\r\n$.extend({\r\n    getOrCreateDialog: function (id) {\r\n        var $box = $('#' + id);\r\n        if (!$box.length) {\r\n            $box = $('<div id=\"' + id + '\"><p></p></div>').hide().appendTo('body');\r\n        }\r\n\r\n        return $box;\r\n    }\r\n});\r\n\r\nfunction showMessage(message) {\r\n    $('#message').html(message + ' <img src=\"/images/ajax-loader.gif\" />').css('left', $(window).width() / 2);\r\n    $('#message').slideDown();\r\n}\r\n\r\nfunction fadeOutMessage() {\r\n    $('#message').fadeOut(500);\r\n}\r\n\r\nfunction confirm(message, callback, options) {\r\n    const defaults = {\r\n        title: 'HRM',\r\n        modal: true,\r\n        resizable: false,\r\n        buttons: [\r\n            {\r\n                text: 'OK',\r\n                class: 'btn btn-primary',\r\n                click: function () {\r\n                    $(this).dialog('close');\r\n                    if (callback !== null) {\r\n                        callback();\r\n                    }\r\n\r\n                    return true;\r\n                }\r\n            },\r\n            {\r\n                text: 'Cancel',\r\n                class: 'btn btn-default',\r\n                click: function () {\r\n                    $(this).dialog('close');\r\n                    return false;\r\n                }\r\n            }\r\n        ],\r\n        minWidth: 300,\r\n        minHeight: 100,\r\n        dialogClass: 'modal-shadow'\r\n    };\r\n\r\n    let $confirm = $.getOrCreateDialog('confirm');\r\n    // set message\r\n    $('p', $confirm).html(message);\r\n    // init dialog\r\n    $confirm.dialog($.extend({}, defaults, options));\r\n}\r\n\r\nfunction showFullAvatar(code, nickname) {\r\n    const defaults = {\r\n        title: nickname,\r\n        modal: true,\r\n        resizable: false,\r\n        dialogClass: 'popup-avatar'\r\n    };\r\n\r\n    $.get(`/employee/avatar/${code}`)\r\n        .done(function (avatarUrl) {\r\n            const avatarHtml = `<img src=\"${avatarUrl}\" style=\"width: 100%; height: 100%\" />`;\r\n\r\n            const $confirm = $.getOrCreateDialog('fullAvatar');\r\n            $confirm.html(avatarHtml);\r\n            $confirm.dialog($.extend({}, defaults));\r\n        })\r\n}\r\n\r\nfunction getParam(name) {\r\n    name = name.replace(/[\\[]/, \"\\\\\\[\").replace(/[\\]]/, \"\\\\\\]\");\r\n    var regexS = \"[\\\\?&]\" + name + \"=([^&#]*)\";\r\n    var regex = new RegExp(regexS);\r\n    var results = regex.exec(window.location.href);\r\n    if (results === null)\r\n        return null;\r\n    else\r\n        return results[1];\r\n}\r\n\r\nfunction alert(message, callback) {\r\n    const defaults = {\r\n        title: 'HRM',\r\n        modal: true,\r\n        resizable: false,\r\n        buttons: [\r\n            {\r\n                text: 'OK',\r\n                class: 'btn btn-primary',\r\n                click: function () {\r\n                    $(this).dialog('close');\r\n                    if (callback) {\r\n                        callback();\r\n                    }\r\n\r\n                    return false;\r\n                }\r\n            }\r\n        ],\r\n        minHeight: 50,\r\n        width: 680,\r\n        dialogClass: 'modal-shadow'\r\n    };\r\n\r\n    let $alert = $.getOrCreateDialog('alert');\r\n    // set message\r\n    $('p', $alert).html(message);\r\n    // init dialog\r\n    $alert.dialog($.extend({}, defaults));\r\n}\r\n\r\nfunction blockUI() {\r\n    document.getElementById('loadingProcess').style.display = 'block';\r\n}\r\n\r\nfunction unblockUI() {\r\n    document.getElementById('loadingProcess').style.display = 'none';\r\n}\r\n\r\nfunction toastOptions() {\r\n    return {\r\n        tapToDismiss: false,\r\n        closeButton: true,\r\n        progressBar: true,\r\n        positionClass: 'toast-top-center',\r\n        showDuration: 0,\r\n        hideDuration: 0,\r\n        timeOut: 3000,\r\n        extendedTimeOut: 0,\r\n        closeOnHover: false,\r\n        preventDuplicates: true,\r\n        closeHtml: '<button type=\"button\">x</button>'\r\n    };\r\n}\r\n\r\nfunction axiosError(error) {\r\n    if (error.response) {\r\n        let url;\r\n\r\n        switch (error.response.status) {\r\n            case 401:\r\n                url = 'auth/login';\r\n                break;\r\n\r\n            case 404:\r\n                url = 'error/PageNotFound';\r\n                break;\r\n\r\n            case 403:\r\n            case 405:\r\n                url = 'error/AccessDenied';\r\n                break;\r\n\r\n            case 500:\r\n                url = 'error/InternalError';\r\n                break;\r\n        }\r\n\r\n        window.location = resolveClientUrl(url);\r\n    }\r\n}\r\n\r\nfunction reorder(items, startIndex, endIndex) {\r\n    const [removed] = items.splice(startIndex, 1);\r\n    items.splice(endIndex, 0, removed);\r\n\r\n    return [...items];\r\n}\r\n\r\nfunction floatThead(el) {\r\n    $(el).floatThead({\r\n        scrollContainer: function ($table) {\r\n            return $table.closest('.content_scroll');\r\n        },\r\n        position: 'fixed',\r\n        top: 72\r\n    });\r\n\r\n    $('#toggle-left-navigation').on('click', function () {\r\n        $(el).floatThead('reflow');\r\n    });\r\n}\r\n\r\nfunction initFromDateOnChange($fromDate, $toDate) {\r\n    if ($fromDate && $toDate) {\r\n        $fromDate.on(\"change\", function () {\r\n            let toMonth = new Date($toDate.val()).getMonth();\r\n            let fromMonth = new Date($fromDate.val()).getMonth();\r\n            if (fromMonth !== toMonth) {\r\n                $toDate.val($(this).val());\r\n            }\r\n        });\r\n    }\r\n}\r\n\r\nfunction initDatepicker() {\r\n    $('.datepicker').each(function () {\r\n        let $this = $(this);\r\n\r\n        let beforeShowDayHandler = function (mydate) {\r\n            let isEnable = true;\r\n            const disabledDates = $this.attr('disabledDate');\r\n            if (disabledDates && disabledDates.length > 0) {\r\n                const checkdate = moment(mydate),\r\n                    myBadDates = disabledDates.split(',');\r\n                for (let i = 0; i < myBadDates.length; i++) {\r\n                    const date = moment(myBadDates[i]);\r\n                    if (date.isSame(checkdate)) {\r\n                        isEnable = false;\r\n                    }\r\n                }\r\n            }\r\n\r\n            return [isEnable];\r\n        };\r\n        $this.datepicker({\r\n            dateFormat: 'dd M, yy',\r\n            beforeShowDay: beforeShowDayHandler,\r\n            changeMonth: true,\r\n            changeYear: true\r\n        });\r\n\r\n        let mindate = $this.attr('mindate'),\r\n            maxdate = $this.attr('maxdate');\r\n        if (mindate && mindate !== 'null') {\r\n            mindate = mindate.split('/');\r\n            $this.datepicker('option', 'minDate', new Date(mindate[0], mindate[1] - 1, mindate[2]));\r\n        }\r\n\r\n        if (maxdate && maxdate !== 'null') {\r\n            maxdate = maxdate.split('/');\r\n            $this.datepicker('option', 'maxDate', new Date(maxdate[0], maxdate[1] - 1, maxdate[2]));\r\n        }\r\n\r\n        $this.attr('readonly', 'readonly');\r\n        $this.keydown(function (e) {\r\n            const tab = 9, enter = 13;\r\n            if (e.keyCode === tab || e.keyCode === enter) {\r\n                return true;\r\n            }\r\n\r\n            return false;\r\n        });\r\n\r\n        $this.closest('.calendar-form').find('.icon-calendar:not(.disabled)').off('click').on('click', function () {\r\n            if ($this.datepicker('widget').is(':visible')) {\r\n                $this.datepicker('hide');\r\n            } else {\r\n                $this.datepicker('show');\r\n            }\r\n        });\r\n    });\r\n}\r\n\r\nfunction setDateRange(selectedIndex) {\r\n    let fromDate = new Date($('#FromDate').val()).toString('dd MMM, yyyy');\r\n    let toDate = new Date($('#ToDate').val()).toString('dd MMM, yyyy');\r\n    let now = $('#Today').val();\r\n\r\n    switch (parseInt(selectedIndex, 10)) {\r\n        case 0: //default\r\n            break;\r\n\r\n        case 1: //today\r\n            toDate = fromDate = Date.parse(now).toString('dd MMM, yyyy');\r\n            break;\r\n\r\n        case 2: // yesterday\r\n            toDate = fromDate = Date.parse(now).add(-1).days().toString('dd MMM, yyyy');\r\n            break;\r\n\r\n        case 3: //current week\r\n            fromDate = Date.parse(now).moveToDayOfWeek(0, -1).toString('dd MMM, yyyy');\r\n            toDate = Date.parse(now).toString('dd MMM, yyyy');\r\n            break;\r\n\r\n        case 4: //last week\r\n            fromDate = Date.parse(now).moveToDayOfWeek(0, -1).add(-7).days().toString('dd MMM, yyyy');\r\n            toDate = Date.parse(now).moveToDayOfWeek(0, -1).add(-1).days().toString('dd MMM, yyyy');\r\n            break;\r\n\r\n        case 5: //current month\r\n            fromDate = Date.parse(now).moveToFirstDayOfMonth().toString('dd MMM, yyyy');\r\n            toDate = Date.parse(now).toString('dd MMM, yyyy');\r\n            break;\r\n\r\n        case 6: //last month\r\n            fromDate = Date.parse(now).add(-1).months().moveToFirstDayOfMonth().toString('dd MMM, yyyy');\r\n            toDate = Date.parse(now).add(-1).months().moveToLastDayOfMonth().toString('dd MMM, yyyy');\r\n            break;\r\n\r\n        case 7: //since last month\r\n            fromDate = Date.parse(now).add(-1).months().moveToFirstDayOfMonth().toString('dd MMM, yyyy');\r\n            toDate = Date.parse(now).toString('dd MMM, yyyy');\r\n            break;\r\n    }\r\n\r\n    $('#FromDate').val(fromDate);\r\n    $('#ToDate').val(toDate);\r\n}\r\n\r\nfunction showValidationSummaryErrors(messages) {\r\n    $('.validation-summary-valid').show();\r\n    $('.validation-summary-valid').addClass('validation-summary-errors');\r\n    let msgWrp = $('.validation-summary-valid').find('ul:first');\r\n    messages.forEach(function (msg) {\r\n        msgWrp.append('<li>' + msg + '</li>');\r\n    });\r\n}\r\n\r\nfunction hideValidationSummaryErrors(isReset) {\r\n    if (isReset) {\r\n        $('.validation-summary-errors').addClass('validation-summary-valid').removeClass('validation-summary-errors');\r\n    }\r\n    let msgWrp = $('.validation-summary-valid').removeClass('validation-summary-errors');\r\n    msgWrp.find('ul:first').html('');\r\n    $('.validation-summary-valid').hide();\r\n}\r\n\r\nfunction autoIndex() {\r\n    var index = 0;\r\n    $('tr').each(function () {\r\n        $(this).children(\"td\").eq(0).html(index);\r\n        index = index + 1;\r\n    });\r\n}\r\n\r\nfunction resolveClientUrl(relativePath) {\r\n    return _rootUrl + relativePath;\r\n}\r\n\r\nfunction initTooltip() {\r\n    $('.tooltip-tipsy').tipsy({\r\n        html: true,\r\n        gravity: 'e'\r\n    });\r\n}\r\n\r\nfunction downloadFile(data, fileName) {\r\n    const url = window.URL.createObjectURL(new Blob([data]));\r\n    const link = document.createElement('a');\r\n    link.href = url;\r\n    link.setAttribute('download', fileName);\r\n    document.body.appendChild(link);\r\n    link.click();\r\n    link.parentNode.removeChild(link);\r\n    window.URL.revokeObjectURL(url);\r\n}\r\n\r\nfunction sortTable(table, th) {\r\n    let getCellValue = function (row, index) {\r\n        let $td = $(row).children('td').eq(index);\r\n        let datetimeAttr = $td.attr('data-datetime');\r\n\r\n        if (typeof datetimeAttr !== typeof undefined && datetimeAttr !== false) {\r\n            return $td.data('datetime');\r\n        }\r\n\r\n        return $td.text().trim().toLowerCase();\r\n    };\r\n    let refreshSorting = function () {\r\n        $('th.col-sorter').each(function () {\r\n            $(this).find('div.fa').removeClass('fa-sort-asc').removeClass('fa-sort-desc');\r\n        });\r\n    };\r\n\r\n    let $icon = $(th).find('div.fa');\r\n    if ($icon.hasClass('fa-sort-desc')) {\r\n        $icon.removeClass('fa-sort-desc').addClass('fa-sort-asc');\r\n    } else if ($icon.hasClass('fa-sort-asc')) {\r\n        $icon.removeClass('fa-sort-asc').addClass('fa-sort-desc');\r\n    } else {\r\n        refreshSorting();\r\n        $icon.addClass('fa-sort-desc');\r\n    }\r\n\r\n    const colIndex = $(th).index();\r\n    let rows = $(table).find('tbody tr').toArray().sort(function (a, b) {\r\n        let valA = getCellValue(a, colIndex),\r\n            valB = getCellValue(b, colIndex);\r\n\r\n        if ($.isNumeric(valA) && $.isNumeric(valB)) {\r\n            return valA - valB;\r\n        } else if (moment(valA).isValid() && moment(valB).isValid()) {\r\n            const dateA = new Date(valA),\r\n                dateB = new Date(valB);\r\n            return dateA - dateB;\r\n        } else {\r\n            return valA.localeCompare(valB, 'vi', { sensitivity: 'base' });\r\n        }\r\n    });\r\n\r\n    if (!$icon.hasClass('fa-sort-asc')) {\r\n        rows = rows.reverse();\r\n    }\r\n\r\n    for (let i = 0; i < rows.length; i++) {\r\n        $(table).append(rows[i]);\r\n    }\r\n}\r\n\r\nfunction debounce(func, wait) {\r\n    let timeout;\r\n    return function (...theArgs) {\r\n        const context = this,\r\n            args = theArgs;\r\n\r\n        const later = () => {\r\n            func.apply(context, args);\r\n        };\r\n\r\n        clearTimeout(timeout);\r\n        timeout = setTimeout(later, wait || 500);\r\n    };\r\n}\r\n\r\nexport {\r\n    showMessage,\r\n    fadeOutMessage,\r\n    confirm,\r\n    blockUI,\r\n    alert,\r\n    unblockUI,\r\n    toastOptions,\r\n    axiosError,\r\n    reorder,\r\n    floatThead,\r\n    initDatepicker,\r\n    initFromDateOnChange,\r\n    setDateRange,\r\n    getParam,\r\n    showValidationSummaryErrors,\r\n    hideValidationSummaryErrors,\r\n    autoIndex,\r\n    resolveClientUrl,\r\n    initTooltip,\r\n    downloadFile,\r\n    sortTable,\r\n    showFullAvatar,\r\n    debounce\r\n};","import React, { PureComponent } from 'react';\r\nimport { Dropdown, MenuItem } from 'react-bootstrap';\r\n\r\nexport default class DropdownOrder extends PureComponent {\r\n    render() {\r\n        return (\r\n            <Dropdown id={this.props.id} componentClass=\"div\" className=\"customize-order\">\r\n                <Dropdown.Toggle noCaret useAnchor>\r\n                    <i className=\"icon icon-sortable\" title=\"Customize order\" />\r\n                </Dropdown.Toggle>\r\n                <Dropdown.Menu>\r\n                    <MenuItem onClick={this.props.onMoveUp}>Up</MenuItem>\r\n                    <MenuItem onClick={this.props.onMoveDown}>Down</MenuItem>\r\n                    <MenuItem onClick={this.props.onMoveTop}>Top</MenuItem>\r\n                    <MenuItem onClick={this.props.onMoveBottom}>Bottom</MenuItem>\r\n                </Dropdown.Menu>\r\n            </Dropdown>\r\n        );\r\n    }\r\n}","import React, { PureComponent } from 'react';\r\nimport { ToastContainer, Slide } from 'react-toastify';\r\n\r\nexport default class ToastLayout extends PureComponent {\r\n    render() {\r\n        return (\r\n            <ToastContainer\r\n                position=\"top-center\"\r\n                autoClose={3000}\r\n                hideProgressBar={false}\r\n                transition={Slide}\r\n                closeOnClick={false}\r\n                draggable={false}\r\n            >\r\n                {this.props.children}\r\n            </ToastContainer>\r\n        );\r\n    }\r\n}"],"sourceRoot":""}
